GC=2032.3
def yr(mjd): return 2000+(mjd-51544.5)/365.25
print('| # | B1950 (1972 label) | J2000 | bits | N (H units) | P from map (s) | P 1970/71 (s), Sagan T1 | P modern (s) @epoch | Pdot | spin-down epoch | map angle / true l | r/GC (r kpc if R0=10) | |z| from tick (kpc) | b from tick / true |b| | modern dist kpc (DIST; DM) |')
for i,(b,j,sid,bits,pt1,ang,r,tick,brk,P0,P1,pe,dist,ddm,gl,gb) in enumerate(P,1):
    N=int(bits,2); pm=N/F
    t=yr(pe)+(pm-P0)/P1/(365.25*86400)
    rk=r/GC*10
    z = (r-tick)/GC*10 if tick else None
    bm = math.degrees(math.atan2(r-tick, r)) if tick else None
    print(f"| {i} | {b} ({sid}) | {j} | {len(bits)} | {N} | {pm:.10f} | {pt1:.10f} | {P0} @{yr(pe):.1f} | {P1:.3e} | {t:.1f} | {ang:.1f} / {gl:.1f} | {r/GC:.4f} ({rk:.2f}) | {('%.3f'%z) if z is not None else 'not resolved'} | {('%.1f'%bm) if bm is not None else '-'} / {abs(gb):.1f} | {dist}; {ddm} |")
